// TH18 v1.00a st01.ecl::MainSub01 wave (s1475-1510) and closures:
// GirlRedA01 1238-1245 / GirlBlueA01 778-785 -> GirlA01 359-379 -> GirlA01_at 380-438;
// GirlC01 843-870 -> async GirlC01_at 871-927. No source timeout.
// Card t0 = main spawn; source wave t0 (MainSub01 entry) = card 124, see report.md.
const TIME_LIMIT: int = 1080;
const TH18_BALL: int = 416;        // source type4 Ball, radius4
const TH18_RING_BALL2: int = 464;  // source type7 RingBall2, radius4

// GirlA01_at body; etNew/config once, etOn re-reads player aim each round.
// Source calls this after GirlA01's wait(30), so the random wait is sampled there.
async sub a01_shoot() {
    wait(30);
    var rank: int = global(GVAR_RANK);
    var w: int = 160 + rand(60);          // source E/N 160+rand%60
    if rank == 2 { w = 40 + rand(60); }   // source H 40+rand%60
    if rank == 3 { w = 1 + rand(60); }    // source L 1+rand%60
    wait(w);
    var n: int = 1;                       // source etCount per rank:1/1/1/3
    var speed: fx = 1.5fx;
    var rounds: int = 1;
    if rank == 2 { speed = 3fx; }
    if rank == 3 { n = 3; speed = 4fx; rounds = 3; }
    sh_reset(0);
    sh_sprite(0, TH18_BALL, 6);           // etSprite(0,4,6)
    sh_aim(0, 1);                         // etAim(0,0): aimed fan
    sh_ring(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, 0deg, 30deg);             // etAngle(0,0,0.5235988)
    sh_speed(0, speed, 0fx);              // M=1 -> first endpoint only
    // etEx(0,0,2,1,...): id0 async0 type2(ANIM) a=1; position retreats 4*initial speed.
    // Animation slowdown/no-hit window omitted by policy; the retreat is kept.
    sh_dist(0, -4fx * speed);
    for i in 0..rounds {
        var fire: int = 1;
        if rank == 1 {
            // unless (DIFF>=2 || RAND%3==0): N only, one body pass.
            if rand(3) != 0 { fire = 0; }
        }
        if fire != 0 { sh_fire(0); }
        if rank == 3 { wait(60); } else { wait(30); }
    }
}

// GirlA01(1) main body. M variants (mirror=1) reflect velocity x:
// target angle 35deg becomes 180-35=145deg; 90deg spawn direction is unchanged.
// Source angle slot (120fr, mode1 t^2) and speed slot (300fr, mode1) advance
// independently; target move_speed cancels an in-flight move_angle, so write
// both per frame from the two analytic curves.
async sub girl_a01(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);                    // setHurtbox(24,24)
    set_hitbox(8fx);                      // setHitbox(16,16)
    if global(GVAR_RANK) != 0 { spawn a01_shoot(); } // !NHL gate
    var delta: int = -10012;              // 35deg target minus 90deg start
    if mirror != 0 { delta = 10012; }
    move_vel(0, 90deg, 1fx, EASE_LINEAR);
    wait(30);
    for k in 1..301 {
        var kk: int = k;
        if kk > 120 { kk = 120; }
        var off: int = delta * kk * kk / 14400;
        var u: fx = (k as fx) / 300fx;
        var u2: fx = u * (k as fx) / 300fx;
        var speed: fx = 1fx + 1.5fx * u2;
        move_vel(0, 90deg + (off as angle), speed, EASE_LINEAR);
        wait(1);
    }
    loop { wait(1000); }
}

// GirlC01_at loop; configured once, etOn repeats.
async sub girl_c_shoot() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var n: int = 3;                       // etCount 3/3/7/11
    var delta: angle = 30deg;             // etAngle ang2
    var speed: fx = 1fx;
    var rounds: int = 1;                  // diffI(B,1,5,8,60)
    var gap: int = 110;
    if rank == 1 { rounds = 5; }
    if rank == 2 { n = 7; delta = 20deg; speed = 3fx; rounds = 8; gap = 20; }
    if rank == 3 { n = 11; delta = 20deg; speed = 3.5fx; rounds = 60; gap = 10; }
    sh_reset(0);
    sh_sprite(0, TH18_RING_BALL2, 2);     // etSprite(0,7,2)
    sh_aim(0, 1);                         // etAim(0,0)
    sh_ring(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, 0deg, delta);
    sh_speed(0, speed, 0fx);
    sh_dist(0, -4fx * speed);             // EX type2 ANIM a=1: 4*initial speed retreat
    for i in 0..rounds {
        sh_fire(0);
        wait(gap);
    }
}

// GirlC01 843-870: FINAL_X=0 so moveSetMirror is skipped.
async sub girl_c() {
    set_invuln(65535);
    set_hurtbox(16fx);                    // setHurtbox(32,32)
    set_hitbox(12fx);                     // setHitbox(24,24)
    move_vel(0, 90deg, 2fx, EASE_LINEAR);
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN);  // moveVelTime(80,1,pi/2,0)
