// MainSub01b: async first run one frame after MainSub01, then 8x40.
async sub wave_left() {
    for i in 0..8 {
        _ = spawn_enemy(-120fx, -32fx, 100, 0, 0, 0, girl_a01(0));
        _ = spawn_enemy(-184fx, -32fx, 100, 0, 0, 0, girl_a01(0));
        wait(40);
