}

// MainSub01 main ordering. Parent (control enemy) sits at (0,0); enmCreateM
// children get mirror=1, the non-M left group mirror=0.
async sub pattern() {
    wait(120);                            // opening buffer
    spawn c_spawn();
    spawn wave_left();
    for i in 0..8 {
        _ = spawn_enemy(120fx, -32fx, 100, 0, 0, 0, girl_a01(1));
        _ = spawn_enemy(184fx, -32fx, 100, 0, 0, 0, girl_a01(1));
        wait(40);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);     // control enemy: no body collision
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
